function normalizeName(name) {
  return String(name || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim()
}

export function getServiceLogo(service = {}) {
  const name = normalizeName(service.name)
  const byName = BRANDS.find(([, aliases]) =>
    aliases.some(alias => name === alias || name.startsWith(alias + ' '))
  )
  const domain = String(service.website || '').trim().toLowerCase()
    .replace(/^https?:\/\//, '').replace(/^www\./, '').split(/[/?#:]/)[0]
  const brand = byName || BRANDS.find(([, , domains]) =>
    domains.some(host => domain === host || domain.endsWith('.' + host))
  )
  return brand && SERVICE_LOGOS[brand[0]] ? { key: brand[0], src: SERVICE_LOGOS[brand[0]] } : null
}
